// Parse Resend webhook event
// Resend sends: email.bounced, email.complained, email.delivery_delayed
const body = $input.first().json.body;

if (!body || !body.type) {
  return [{ json: { error: 'Invalid webhook payload' } }];
}

const eventType = body.type;
const data = body.data || {};

// Map Resend event types
let bounceType = 'unknown';
let severity = 'soft';

switch (eventType) {
  case 'email.bounced':
    bounceType = 'bounce';
    severity = 'hard';
    break;
  case 'email.complained':
    bounceType = 'complaint';
    severity = 'hard';
    break;
  case 'email.delivery_delayed':
    bounceType = 'delayed';
    severity = 'soft';
    break;
  default:
    bounceType = eventType;
}

return [{
  json: {
    event_type: eventType,
    bounce_type: bounceType,
    severity: severity,
    to_email: data.to?.[0] || data.email_id,
    from_email: data.from || '',
    resend_email_id: data.email_id || data.id,
    reason: data.bounce?.message || data.reason || '',
    bounce_code: data.bounce?.status_code || '',
    timestamp: data.created_at || new Date().toISOString()
  }
}];

// Determine action based on bounce severity
const bounce = $('Parse Bounce Event').first().json;
const lead = $input.first().json;

if (!lead || !lead.id) {
  return [{ json: { unmatched: true, email: bounce.to_email, bounce_type: bounce.bounce_type } }];
}

const isHardBounce = bounce.severity === 'hard';

return [{
  json: {
    lead_id: lead.id,
    lead_email: lead.email,
    lead_name: `${lead.first_name || ''} ${lead.last_name || ''}`.trim(),
    is_hard_bounce: isHardBounce,
    bounce_type: bounce.bounce_type,
    reason: bounce.reason,
    bounce_code: bounce.bounce_code,
    // Hard bounce: invalidate email, pause cadence, mark bounced
    // Soft bounce: log only, retry on next cadence step
    lead_update: isHardBounce ? {
      status: 'bounced',
      email_validated: false,
      cadence_paused: true
    } : {},
    interaction: {
      lead_id: lead.id,
      type: isHardBounce ? 'email_hard_bounced' : 'email_soft_bounced',
      channel: 'email',
      metadata: {
        bounce_type: bounce.bounce_type,
        reason: bounce.reason,
        bounce_code: bounce.bounce_code,
        resend_email_id: bounce.resend_email_id,
        from_email: bounce.from_email
      }
    },
    // Domain reputation tracking
    from_domain: bounce.from_email ? bounce.from_email.split('@')[1] : null
  }
}];

// Update domain reputation on hard bounce
const data = $input.first().json;

if (!data.from_domain) return [];

// Track bounce for domain health
return [{
  json: {
    domain: data.from_domain,
    note: 'CONFIGURE: Increment domain bounce counter via Supabase RPC',
    query: `UPDATE email_domains SET reputation_score = GREATEST(0, reputation_score - 5) WHERE domain = '${data.from_domain}'`
  }
}];
